def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
def lcm(a, b):
    return a * b // gcd(a, b)
print(gcd(48, 36), gcd(17, 5), lcm(4, 6), lcm(21, 6), gcd(0, 7))

def qsort(a):
    if len(a) <= 1:
        return a
    p = a[0]
    left = []
    right = []
    for x in a[1:]:
        if x < p:
            left.append(x)
        else:
            right.append(x)
    return qsort(left) + [p] + qsort(right)
print(qsort([8, 3, 9, 1, 5, 5, 2, 7]))

class Vec:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __add__(self, o):
        return Vec(self.x + o.x, self.y + o.y)
    def __sub__(self, o):
        return Vec(self.x - o.x, self.y - o.y)
    def __mul__(self, k):
        return Vec(self.x * k, self.y * k)
    def __eq__(self, o):
        return self.x == o.x and self.y == o.y
    def __str__(self):
        return '(' + str(self.x) + ',' + str(self.y) + ')'
v1 = Vec(1, 2)
v2 = Vec(3, 4)
print(v1 + v2, v2 - v1, v1 * 3)
print(v1 + v2 == Vec(4, 6), v1 == v2)

def shout(fn):
    def wrapped(x):
        return '!!' + str(fn(x)) + '!!'
    return wrapped
def double(x):
    return x * 2
loud = shout(double)
print(loud(21))
def compose(f, g):
    return lambda x: f(g(x))
inc = lambda x: x + 1
print(compose(double, inc)(5), compose(inc, double)(5))

def flatten(x):
    out = []
    for item in x:
        if isinstance(item, list):
            for sub in flatten(item):
                out.append(sub)
        else:
            out.append(item)
    return out
print(flatten([1, [2, [3, [4, 5]], 6], 7]))
print(flatten([]), flatten([[[[]]]]))
print(flatten([1, [2], [[3], 4], 'ab']))

